// Helper function to count integers in the input sequence
function CountIntegers(values: seq<object>): int
    reads values
{
    var count := 0;
    var len := |values|;
    // Count the number of integers in values
    if len == 0 then
        count := 0;
    else {
        count := CountIntegers(values[1..]); // Recursive call on the tail
        if values[0] is int then
            count := count + 1; // Increment count if the head is an integer
    }
    count
}
